---@class ThrowPoleService
local ThrowPoleService = Class("ThrowPoleService")

function ThrowPoleService.new(from)
    local obj = ThrowPoleService.New()
    obj.luaDialog = from
    for k, v in pairs(from) do
        obj[k]=v
    end
    return obj
end

function ThrowPoleService:UpdateInfo()
    --CfUtils.PlayAnimation(self.LeftPanel, "FishPoolGoFishingDialog_LeftPanel_Fishing")
    self._circleLoopTime = FishingUtils.GetFishQTELoopTime()

    self.eventProxy = UIEventProxy.Create(self.ThrowPole.gameObject)
    --proxy2.onPointerDown = Bind(self, self.OnBtnThrowPole, false)
end

function ThrowPoleService:ShowMe()
    self:UpdateInfo()
    self:FillSelectCircle()
    KTool.SetActive(self.ThrowPole, true)
end

function ThrowPoleService:HideMe()
    self._isUpdateCircle = false
    KTool.SetActive(self.ThrowPole, false)
end

function ThrowPoleService:OnUpdate()
    --黄色的圈圈
    if self._isUpdateCircle then
        self._updateCircleTime = self._updateCircleTime + (CS.UnityEngine.Time.deltaTime * self._dir)
        if self._updateCircleTime >= self._circleLoopTime then
            self._dir = -1
            self._updateCircleTime = self._circleLoopTime
        elseif self._updateCircleTime <= 0 then
            self._dir = 1
            self._updateCircleTime = 0
        end
        local scale = self._updateCircleTime / self._circleLoopTime

        self.ImgYellowCircle.localScale = Vector3(scale, scale, scale)
        --引导 必当完美
        if self._isGuide then
            local type = self:GetCastRodType(self._updateCircleTime / self._circleLoopTime)
            if type == ConstantsFishing.CastRodType.Perfect then

                self._isUpdateCircle = false
                Events.Broadcast(Constants.EventNames.EVENT_GUIDE_WAIT_ANIMATE_EXECUTE_COMPLETE)
            end
        end
    end
end

function ThrowPoleService:OnClick(isAuto, callBack)
    if FishingUtils.IsAutoing() and not isAuto then
        return
    end

    self._isUpdateCircle = false
    if self._isThrowReq then
        return
    end
    self._isThrowReq = true

    local type = self:GetCastRodType(self._updateCircleTime / self._circleLoopTime)
    fishingComponent:FishingCastingReq(self.placeId, type, function(fishId)

        CfUtils.StartCoroutineWithBlocker(function()
            fishId = checkNumber(fishId)
            if type == ConstantsFishing.CastRodType.Perfect then
                CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_throw_perfect)
            elseif type == ConstantsFishing.CastRodType.Well then
                CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_throw_good)
            elseif type == ConstantsFishing.CastRodType.Generally then
                CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_throw_normal)
            end

            KTool.SetActive(self.ImgText, true)
            CfUtils.SetUISwitchImage(self.ImgStatus, type)


            local aniGo = self.UIFX_FishPoolGoFishingNormal
            if type == ConstantsFishing.CastRodType.Perfect then
                aniGo = self.UIFX_FishPoolGoFishingPerfect
            elseif type == ConstantsFishing.CastRodType.Well then
                aniGo = self.UIFX_FishPoolGoFishingGood
            end
            KTool.SetActive(aniGo, true)

            cs_coroutine.start(function()
                self:FillQTEBuff(type)
                cs_coroutine.yield_return(WaitForSeconds(3.5))
                self:ClearQTEBuff()
            end)

            coroutine.yield(WaitForSeconds(1))
            KTool.SetActive(self.ImgText, false)
            KTool.SetActive(aniGo, false)

            self:HideMe()

            --播一下抛竿动作
            self.roleAnimServer:PlayCastRodAnimation(type)

            --说话
            local talkType = "10"..type
            self.leftPanelServer:RefreshRoleTalk(talkType, fishId)

            local time = 1.2
            if type == ConstantsFishing.CastRodType.Perfect then
                time = 1.35
            elseif type == ConstantsFishing.CastRodType.Well then
                time = 1.5
            end
            coroutine.yield(WaitForSeconds(time))
            KTool.SetActive(self.PerfectNode, false)

            CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_bait)

            FishingMgr:GetInstance():SetShuiHuaEffectActive(true, type)
            KTool.SetActive(self.TipAnimNode, true)
            coroutine.yield(WaitForSeconds(1))
            FishingMgr:GetInstance():SetShuiHuaEffectActive(false)

            coroutine.yield(WaitForSeconds(0.5))
            KTool.SetActive(self.TipAnimNode, false)

            callBack(fishId, type)

            self._isThrowReq = false
        end, function()
            self.luaDialog:TransferTo(EGoFishState.Ready)
            self._isThrowReq = false
        end)
    end)
end

function ThrowPoleService:AddClickListener(target, callBack)
    if target then
        self.eventProxy.onPointerDown = Bind(target, callBack)
    else
        self.eventProxy.onPointerDown = nil
    end
end

--绘制抛竿选择圆环界面
function ThrowPoleService:FillSelectCircle()
    self:RefreshCircle()
    self.ImgYellowCircle.localScale = Vector3(1, 1, 1)
    self._updateCircleTime = 0
    self._dir = 1
    self._isUpdateCircle = true
end

--绘制圆环
function ThrowPoleService:RefreshCircle()
    local defaultRect = self.ImgWhiteCircle.rect
    local defaultW, defaultH = defaultRect.width, defaultRect.height

    local prefectWeight = FishingUtils.GetPerfectWeight()
    local wellWeight = FishingUtils.GetWellWeight()
    local generallyWeight = FishingUtils.GetGenerallyWeight()
    local allWeight = prefectWeight + wellWeight + generallyWeight    --总权重

    local intervalStrs =  FishingUtils.GetPerfectAndWellInterval()
    local interval = CfUtils.Split(intervalStrs)                      --区间

    --先随良好圈外圈半径
    local wellOutRadius = math.random(checkNumber(interval[1]) + wellWeight, checkNumber(interval[2]) - wellWeight)
    local wellInRadius = wellOutRadius - wellWeight

    --陪钓人的加成
    local cardAddNum = FishingUtils.GetFishingAdditionValueByAccompanyCard(self.placeId, ConstantsFishing.AdditionType.AddCastRange)

    --完美圈加成
    prefectWeight = prefectWeight * (1 + FishingUtils.GetFishingPropsAdditionValue(ConstantsFishing.AdditionType.AddCastRange, nil, self.placeId) + cardAddNum)
    --随完美圈外圈半径
    local prefectOutRadius = math.random(checkInt(wellInRadius + prefectWeight), checkInt(wellOutRadius - prefectWeight))
    local prefectInRadius = prefectOutRadius - prefectWeight
    prefectOutRadius = wellInRadius + wellWeight / 2 + prefectWeight/2
    prefectInRadius = wellInRadius + wellWeight / 2 - prefectWeight/2

    self._castRodMap = {}
    local scaleOut = prefectOutRadius / allWeight
    self.ImgGreenCirceOut.sizeDelta = Vector2(defaultW * scaleOut, defaultH * scaleOut)
    local scaleIn = prefectInRadius / allWeight
    self.ImgGreenCirceIn.sizeDelta = Vector2(defaultW * scaleIn, defaultH * scaleIn)
    table.insert(self._castRodMap, {
        min = scaleIn,
        max = scaleOut,
        type = ConstantsFishing.CastRodType.Perfect
    })

    scaleOut = wellOutRadius / allWeight
    self.ImgBlueCircleOut.sizeDelta = Vector2(defaultW * scaleOut, defaultH * scaleOut)
    scaleIn = wellInRadius / allWeight
    self.ImgBlueCircleIn.sizeDelta = Vector2(defaultW * scaleIn, defaultH * scaleIn)
    table.insert(self._castRodMap, {
        min = scaleIn,
        max = scaleOut,
        type = ConstantsFishing.CastRodType.Well
    })

    KTool.SetActive(self.RingEffect, true)
end

--获取抛竿类型
function ThrowPoleService:GetCastRodType(num)
    if not self._castRodMap then
        return ConstantsFishing.CastRodType.Generally
    end
    for k, v in pairs(self._castRodMap) do
        if num >= v.min and num <= v.max then
            return v.type
        end
    end
    return ConstantsFishing.CastRodType.Generally
end

--qte的buff
function ThrowPoleService:FillQTEBuff(type)
    local vo = FishingUtils.GetFishingTierodBonusVo(type)
    if not vo then
        return
    end

    local t = FishingUtils.GetAdditionDataByVo(vo)
    if not t then
        return
    end

    for k, v in pairs(t) do
        local go = self.LayoutBuffTips.transform:Find("TipsNode"..k)
        if not go then
            go = CfUtils.InstantiateGo(self.TipsNode, self.LayoutBuffTips)
            go.name = "TipsNode"..k
        end
        local animRootGo = go.transform:Find("AnimRoot")

        local str, value = FishingUtils.GetAdditionDesc(v, true)
        CfUtils.FillText(animRootGo.transform:Find("Text"), str)
        CfUtils.FillText(animRootGo.transform:Find("TxtNumber"), "+"..checkInt(checkNumber(value) * 100).."%")

        KTool.SetActive(go, true)
        CfUtils.PlayAnimator(animRootGo, "Go")
    end
end

--隐藏qtebuff
function ThrowPoleService:ClearQTEBuff()
    for i = 1, self.LayoutBuffTips.childCount do
        local go = self.LayoutBuffTips:GetChild(i - 1)
        if go then
            KTool.SetActive(go, false)
        end
    end
end

return ThrowPoleService